import React, { useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom"; // ✅ FIX: import useNavigate

export default function AddDriverForm() {
  const navigate = useNavigate(); // ✅ FIX: initialize useNavigate

  const [form, setForm] = useState({
    name: "",
    email: "",
    phone: "",
    licenseNumber: "",
    status: "active",
    isAvailable: true,
    currentOrders: 0,
    lat: "",
    lng: ""
  });

  const [message, setMessage] = useState("");

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setForm((prev) => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      await axios.post("http://localhost:5000/api/drivers", {
        ...form,
        location: {
          lat: parseFloat(form.lat),
          lng: parseFloat(form.lng),
        },
      });

      setMessage("✅ Driver added successfully!");
      setForm({
        name: "",
        email: "",
        phone: "",
        licenseNumber: "",
        status: "active",
        isAvailable: true,
        currentOrders: 0,
        lat: "",
        lng: ""
      });
    } catch (error) {
      console.error(error);
      setMessage("❌ Failed to add driver");
    }
  };

  return (
    <form onSubmit={handleSubmit} style={{ padding: "20px", maxWidth: "400px", margin: "auto" }}>
      <h2>Add Driver</h2>

      {["name", "email", "phone", "licenseNumber", "lat", "lng"].map((field) => (
        <input
          key={field}
          name={field}
          placeholder={field}
          value={(form as any)[field]}
          onChange={handleChange}
          style={{ marginBottom: "10px", width: "100%", padding: "8px" }}
          required
        />
      ))}

      <div style={{ display: "flex", gap: "10px", marginTop: "10px" }}>
        <button type="submit" style={{ padding: "10px 20px" }}>Add Driver</button>
        <button
          type="button"
          style={{ padding: "10px 20px", backgroundColor: "#6c757d", color: "#fff", border: "none", borderRadius: "4px" }}
          onClick={() => navigate("/")} // ✅ fixed usage
        >
          ← Back to Dashboard
        </button>
      </div>

      {message && (
        <p style={{ color: message.includes("✅") ? "green" : "red", marginTop: "15px" }}>
          {message}
        </p>
      )}
    </form>
  );
}
